/* Product Cards - Enhanced Design */
.product-card {
    -fx-background-color: white;
    -fx-background-radius: 16px;
    -fx-border-color: #e5e7eb;
    -fx-border-radius: 16px;
    -fx-border-width: 2px;
    -fx-effect: dropshadow(gaussian, rgba(0, 0, 0, 0.1), 15, 0, 0, 5);
}

.product-card:hover {
    -fx-border-color: #667eea;
    -fx-effect: dropshadow(gaussian, rgba(102, 126, 234, 0.4), 20, 0, 0, 8);
    -fx-translate-y: -5;
}

/* Clickable Product Card */
.clickable-card {
    -fx-cursor: hand;
}

.clickable-card:hover {
    -fx-scale-x: 1.03;
    -fx-scale-y: 1.03;
    -fx-border-color: #667eea;
    -fx-effect: dropshadow(gaussian, rgba(102, 126, 234, 0.5), 25, 0, 0, 10);
}

/* Product image placeholder with gradient */
.product-image {
    -fx-background-color: linear-gradient(to bottom right, #f3f4f6 0%, #e5e7eb 100%);
