}

.product-price {
    -fx-text-fill: #667eea;
    -fx-font-size: 14px;
    -fx-font-weight: 900;
    -fx-wrap-text: true;
    -fx-text-alignment: center;
    -fx-max-width: 260;
}

.product-price-discount {
    -fx-text-fill: #ef4444;
    -fx-font-size: 14px;
    -fx-font-weight: 900;
    -fx-wrap-text: true;
