    -fx-text-fill: white;
    -fx-border-color: transparent;
    -fx-font-weight: 800;
    -fx-effect: dropshadow(gaussian, rgba(102, 126, 234, 0.8), 25, 0, 0, 12);
}

.electronics-filter-active:hover {
    -fx-scale-x: 1.1;
    -fx-scale-y: 1.1;
}

.electronics-status {
    -fx-text-fill: #667eea;
    -fx-font-size: 15px;
    -fx-font-weight: 700;
    -fx-background-color: rgba(102, 126, 234, 0.15);
    -fx-background-radius: 20px;
    -fx-padding: 12px 24px;
    -fx-effect: dropshadow(gaussian, rgba(102, 126, 234, 0.3), 15, 0, 0, 5);
}

.electronics-scroll {
    -fx-background-color: transparent;
    -fx-background: linear-gradient(to bottom, #fafafa 0%, #f0f0f5 100%);
}

.electronics-scroll .viewport {
    -fx-background-color: transparent;
}

.electronics-scroll .scroll-bar:vertical {
    -fx-background-color: transparent;
    -fx-pref-width: 10;
}

.electronics-scroll .scroll-bar:vertical .track {
    -fx-background-color: rgba(102, 126, 234, 0.15);
    -fx-background-radius: 10px;
}

.electronics-scroll .scroll-bar:vertical .thumb {
    -fx-background-color: linear-gradient(to bottom, #667eea 0%, #764ba2 100%);
    -fx-background-radius: 10px;
    -fx-effect: dropshadow(gaussian, rgba(102, 126, 234, 0.5), 12, 0, 0, 3);
}

.electronics-scroll .scroll-bar:vertical .thumb:hover {
    -fx-background-color: linear-gradient(to bottom, #764ba2 0%, #f093fb 100%);
}

.electronics-scroll .scroll-bar:vertical .increment-button,
.electronics-scroll .scroll-bar:vertical .decrement-button {
    -fx-background-color: transparent;
    -fx-padding: 0;
}

/* Glowing Product Cards for Electronics - Strong visible borders */
.electronics-scroll .product-card,
.product-card {
    -fx-background-color: white;
    -fx-background-radius: 16px;
    -fx-border-color: #e5e7eb;
    -fx-border-radius: 16px;
    -fx-border-width: 2px;
    -fx-effect: dropshadow(gaussian, rgba(0, 0, 0, 0.1), 15, 0, 0, 5);
}

.electronics-scroll .product-card:hover,
.product-card:hover {
    -fx-border-color: #667eea;
    -fx-effect: dropshadow(gaussian, rgba(102, 126, 234, 0.4), 20, 0, 0, 8);
    -fx-translate-y: -5;
}

/* Clickable Card with STRONG Glowing Animation */
.clickable-card {
    -fx-cursor: hand;
}

.electronics-scroll .clickable-card:hover,
.clickable-card:hover {
    -fx-scale-x: 1.03;
    -fx-scale-y: 1.03;
    -fx-border-color: #667eea;
    -fx-effect: dropshadow(gaussian, rgba(102, 126, 234, 0.5), 25, 0, 0, 10);
}

/* Colorful Glowing Product Image Container */
.electronics-scroll .product-image,
.product-image {
    -fx-background-color: linear-gradient(to bottom right, #f3f4f6 0%, #e5e7eb 100%);
    -fx-background-radius: 14px 14px 0 0;
    -fx-border-color: #e5e7eb;
    -fx-border-radius: 14px 14px 0 0;
    -fx-border-width: 0 0 2px 0;
}

/* Product Name with Glow */
.product-name {
    -fx-text-fill: #1a202c;
    -fx-font-size: 16px;
    -fx-font-weight: 700;
    -fx-text-alignment: center;
    -fx-wrap-text: true;
    -fx-letter-spacing: 0.5px;
    -fx-line-spacing: 3px;
}

/* Glowing Price Display */
.product-price {
    -fx-text-fill: #667eea;
    -fx-font-size: 14px;
    -fx-font-weight: 800;
    -fx-wrap-text: true;
    -fx-text-alignment: center;
    -fx-max-width: 260;
}

/* Vibrant Glowing Discount Price */
.product-price-discount {
    -fx-text-fill: #ff6b6b;
    -fx-font-size: 14px;
    -fx-font-weight: 800;
    -fx-wrap-text: true;
    -fx-text-alignment: center;
    -fx-max-width: 260;
}

/* SUPER Clear and Glowing Discount Badge */
.product-discount-badge {
    -fx-background-color: linear-gradient(from 0% 0% to 100% 100%, #ff6b6b 0%, #ee5a6f 50%, #ff4757 100%);
    -fx-text-fill: white;
    -fx-font-size: 14px;
    -fx-font-weight: 900;
    -fx-background-radius: 20px;
    -fx-padding: 9px 18px;
    -fx-letter-spacing: 1.2px;
    -fx-effect: dropshadow(gaussian, rgba(255, 71, 87, 0.8), 20, 0, 0, 8);
    -fx-border-color: rgba(255, 255, 255, 0.5);
    -fx-border-radius: 20px;
    -fx-border-width: 2px;
}

/* ===== Standard Product Box Container ===== */

/* Professional Standard Box - Clean and Uniform */
.product-box-standard {
    -fx-background-color: linear-gradient(from 0% 0% to 100% 100%, #667eea 0%, #764ba2 100%);
    -fx-border-color: #5568d3;
    -fx-border-width: 3px;
    -fx-border-radius: 0px;
    -fx-background-radius: 0px;
    -fx-padding: 10px;
    -fx-effect: dropshadow(gaussian, rgba(102, 126, 234, 0.4), 20, 0, 0, 8);
}

.product-box-standard:hover {
    -fx-effect: dropshadow(gaussian, rgba(102, 126, 234, 0.7), 30, 0, 0, 12);
}

/* ===== Modern Fashion-Inspired Additional Styles ===== */

/* Soft Pastel Color Palette Variables (as reference in comments) */
/* Primary: #a8edea (Soft Turquoise) */
/* Secondary: #fed6e3 (Soft Pink) */
/* Accent: #e76f51 (Coral) */
/* Background: #fafafa (Off White) */
/* Text: #2d3748 (Charcoal) */

/* Clean Card Spacing */
.product-card > * {
    -fx-spacing: 8px;
}

/* Smooth Transitions - Applied via JavaFX animations */
.product-card,
.electronics-filter,
.electronics-back-btn,
.clickable-card {
    -fx-transition: all 0.3s ease-in-out;
}

/* ==================== DASHBOARD STYLES ==================== */

/* Sidebar Navigation */
.dashboard-sidebar {
    -fx-background-color: linear-gradient(to bottom, #1e293b 0%, #0f172a 100%);
    -fx-padding: 24px 12px;
    -fx-border-color: rgba(148, 163, 184, 0.22);
    -fx-border-width: 0 1 0 0;
    -fx-effect: dropshadow(gaussian, rgba(15, 23, 42, 0.45), 26, 0, 6, 0);
}

.sidebar-logo {
    -fx-fill: #f8fafc;
    -fx-effect: dropshadow(gaussian, rgba(56, 189, 248, 0.45), 18, 0.15, 0, 0);
}

.sidebar-btn {
    -fx-background-color: transparent;
    -fx-text-fill: #cbd5e1;
    -fx-font-size: 14px;
    -fx-font-weight: 700;
    -fx-padding: 12px 16px;
    -fx-border-radius: 10;
    -fx-background-radius: 10;
    -fx-cursor: hand;
    -fx-text-alignment: left;
    -fx-alignment: center-left;
}

.sidebar-btn:hover {
    -fx-background-color: rgba(56, 189, 248, 0.18);
    -fx-text-fill: #e2e8f0;
    -fx-translate-x: 2px;
}

.sidebar-btn-active {
    -fx-background-color: linear-gradient(to right, #0ea5e9 0%, #2563eb 100%);
    -fx-text-fill: #ffffff;
    -fx-font-size: 14px;
    -fx-font-weight: 800;
    -fx-padding: 12px 16px;
    -fx-border-radius: 10;
    -fx-background-radius: 10;
    -fx-cursor: hand;
    -fx-effect: dropshadow(gaussian, rgba(37, 99, 235, 0.42), 16, 0.2, 0, 4);
}

/* Dashboard Header */
.dashboard-header {
    -fx-background-color: rgba(248, 250, 252, 0.97);
    -fx-border-color: rgba(148, 163, 184, 0.32);
