}

.action-btn-green {
    -fx-background-color: linear-gradient(to right, #22c55e 0%, #16a34a 100%);
    -fx-text-fill: white;
    -fx-font-size: 13px;
    -fx-font-weight: 800;
    -fx-padding: 10px 22px;
    -fx-background-radius: 11;
    -fx-cursor: hand;
    -fx-effect: dropshadow(gaussian, rgba(34, 197, 94, 0.35), 12, 0.2, 0, 2);
}

.action-btn-green:hover {
    -fx-background-color: linear-gradient(to right, #16a34a 0%, #15803d 100%);
    -fx-scale-x: 1.03;
    -fx-scale-y: 1.03;
}

.action-btn-orange {
    -fx-background-color: linear-gradient(to right, #f59e0b 0%, #f97316 100%);
    -fx-text-fill: white;
    -fx-font-size: 13px;
    -fx-font-weight: 800;
    -fx-padding: 10px 22px;
    -fx-background-radius: 11;
    -fx-cursor: hand;
    -fx-effect: dropshadow(gaussian, rgba(245, 158, 11, 0.35), 12, 0.2, 0, 2);
}

.action-btn-orange:hover {
    -fx-background-color: linear-gradient(to right, #d97706 0%, #ea580c 100%);
    -fx-scale-x: 1.03;
    -fx-scale-y: 1.03;
}

.action-btn-purple {
    -fx-background-color: linear-gradient(to right, #a855f7 0%, #7c3aed 100%);
    -fx-text-fill: white;
    -fx-font-size: 13px;
    -fx-font-weight: 800;
    -fx-padding: 10px 22px;
