/* Content Cards */
.content-card {
    -fx-background-color: rgba(248, 250, 252, 0.97);
    -fx-background-radius: 14;
    -fx-border-color: rgba(203, 213, 225, 0.72);
    -fx-border-width: 1;
    -fx-border-radius: 14;
    -fx-effect: dropshadow(gaussian, rgba(15, 23, 42, 0.16), 18, 0.1, 0, 4);
}

.section-title {
    -fx-font-size: 18px;
    -fx-font-weight: 900;
    -fx-text-fill: #0f172a;
}

.chart-placeholder {
    -fx-font-size: 16px;
    -fx-text-fill: #64748b;
    -fx-alignment: center;
}

.activity-item {
    -fx-font-size: 16px;
    -fx-text-fill: #1e293b;
    -fx-font-weight: 700;
}

.activity-amount {
    -fx-font-size: 18px;
    -fx-text-fill: #16a34a;
    -fx-font-weight: 800;
}

.home-status {
    -fx-font-size: 13px;
    -fx-text-fill: #0f172a;
    -fx-font-weight: 700;
