}

/* ==================== CART PAGE STYLES ==================== */

/* Cart Page Title */
.cart-page-title {
    -fx-font-size: 20px;
    -fx-font-weight: bold;
    -fx-text-fill: white;
}

/* Cart Status Label */
.cart-status-label {
    -fx-font-size: 16px;
    -fx-font-weight: bold;
    -fx-text-fill: #333;
    -fx-padding: 10px 0;
}

/* Cart Scroll Pane */
.cart-scroll-pane {
    -fx-background-color: transparent;
    -fx-background: transparent;
    -fx-border-color: transparent;
}

.cart-scroll-pane .viewport {
    -fx-background-color: transparent;
}

/* Cart Items Container */
.cart-items-container {
    -fx-background-color: transparent;
}

/* Cart Item Card */
.cart-item-card {
    -fx-background-color: white;
    -fx-background-radius: 12px;
    -fx-border-color: #e2e8f0;
    -fx-border-radius: 12px;
    -fx-border-width: 1px;
    -fx-effect: dropshadow(gaussian, rgba(0, 0, 0, 0.08), 10, 0, 0, 3);
}

.cart-item-card:hover {
    -fx-effect: dropshadow(gaussian, rgba(0, 0, 0, 0.15), 15, 0, 0, 5);
    -fx-border-color: #667eea;
}

/* Cart Summary Box */
.cart-summary-box {
    -fx-background-color: linear-gradient(from 0% 0% to 100% 100%, #667eea 0%, #764ba2 100%);
    -fx-background-radius: 15px;
    -fx-effect: dropshadow(gaussian, rgba(102, 126, 234, 0.3), 15, 0, 0, 5);
}

.cart-summary-title {
    -fx-font-size: 18px;
    -fx-font-weight: bold;
    -fx-text-fill: white;
}

.cart-summary-label {
    -fx-font-size: 14px;
    -fx-text-fill: rgba(255, 255, 255, 0.9);
}

.cart-summary-value {
    -fx-font-size: 14px;
    -fx-font-weight: bold;
    -fx-text-fill: white;
}

.cart-total-price {
    -fx-font-size: 20px;
    -fx-font-weight: bold;
    -fx-text-fill: #ffeb3b;
}

/* Cart Buttons */
.cart-clear-btn {
    -fx-background-color: rgba(255, 255, 255, 0.2);
    -fx-text-fill: white;
    -fx-font-size: 13px;
    -fx-font-weight: bold;
    -fx-padding: 10px 20px;
    -fx-background-radius: 20px;
    -fx-cursor: hand;
    -fx-border-color: rgba(255, 255, 255, 0.3);
    -fx-border-radius: 20px;
}

.cart-clear-btn:hover {
    -fx-background-color: rgba(231, 76, 60, 0.8);
    -fx-border-color: white;
}

.cart-checkout-btn {
    -fx-background-color: #27ae60;
    -fx-text-fill: white;
    -fx-font-size: 14px;
    -fx-font-weight: bold;
    -fx-padding: 10px 25px;
    -fx-background-radius: 20px;
    -fx-cursor: hand;
    -fx-effect: dropshadow(gaussian, rgba(39, 174, 96, 0.4), 10, 0, 0, 3);
}

.cart-checkout-btn:hover {
    -fx-background-color: #2ecc71;
    -fx-effect: dropshadow(gaussian, rgba(46, 204, 113, 0.6), 15, 0, 0, 5);
    -fx-scale-x: 1.03;
    -fx-scale-y: 1.03;
}

.cart-continue-btn {
    -fx-background-color: linear-gradient(from 0% 0% to 100% 100%, #f093fb 0%, #f5576c 100%);
    -fx-text-fill: white;
    -fx-font-size: 14px;
    -fx-font-weight: bold;
    -fx-padding: 12px 30px;
    -fx-background-radius: 25px;
    -fx-cursor: hand;
    -fx-effect: dropshadow(gaussian, rgba(240, 147, 251, 0.4), 10, 0, 0, 4);
}

.cart-continue-btn:hover {
    -fx-background-color: linear-gradient(from 0% 0% to 100% 100%, #f5576c 0%, #f093fb 100%);
    -fx-effect: dropshadow(gaussian, rgba(245, 87, 108, 0.6), 15, 0, 0, 6);
    -fx-scale-x: 1.05;
    -fx-scale-y: 1.05;
}

/* Cart Button in Page Headers */
.beauty-cart-btn, .electronics-cart-btn {
    -fx-background-color: linear-gradient(from 0% 0% to 100% 100%, #27ae60 0%, #2ecc71 100%);
    -fx-text-fill: white;
    -fx-font-size: 13px;
    -fx-font-weight: bold;
    -fx-padding: 8px 16px;
    -fx-background-radius: 20px;
    -fx-cursor: hand;
    -fx-effect: dropshadow(gaussian, rgba(39, 174, 96, 0.4), 8, 0, 0, 3);
    -fx-margin-right: 10px;
}

.beauty-cart-btn:hover, .electronics-cart-btn:hover {
    -fx-background-color: linear-gradient(from 0% 0% to 100% 100%, #2ecc71 0%, #27ae60 100%);
    -fx-effect: dropshadow(gaussian, rgba(46, 204, 113, 0.6), 12, 0, 0, 5);
    -fx-scale-x: 1.05;
    -fx-scale-y: 1.05;
}

/* Fashion, HomeLiving, NewArrivals Cart Buttons */
.fashion-cart-btn, .homeliving-cart-btn, .newarrivals-cart-btn {
    -fx-background-color: linear-gradient(from 0% 0% to 100% 100%, #27ae60 0%, #2ecc71 100%);
    -fx-text-fill: white;
    -fx-font-size: 13px;
    -fx-font-weight: bold;
    -fx-padding: 8px 16px;
    -fx-background-radius: 20px;
    -fx-cursor: hand;
    -fx-effect: dropshadow(gaussian, rgba(39, 174, 96, 0.4), 8, 0, 0, 3);
}

.fashion-cart-btn:hover, .homeliving-cart-btn:hover, .newarrivals-cart-btn:hover {
    -fx-background-color: linear-gradient(from 0% 0% to 100% 100%, #2ecc71 0%, #27ae60 100%);
    -fx-effect: dropshadow(gaussian, rgba(46, 204, 113, 0.6), 12, 0, 0, 5);
    -fx-scale-x: 1.05;
    -fx-scale-y: 1.05;
}

/* Free Delivery Cart Button */
.freedelivery-cart-btn {
    -fx-background-color: linear-gradient(from 0% 0% to 100% 100%, #27ae60 0%, #2ecc71 100%);
    -fx-text-fill: white;
    -fx-font-size: 13px;
    -fx-font-weight: bold;
    -fx-padding: 8px 16px;
    -fx-background-radius: 20px;
    -fx-cursor: hand;
    -fx-effect: dropshadow(gaussian, rgba(39, 174, 96, 0.4), 8, 0, 0, 3);
}

.freedelivery-cart-btn:hover {
    -fx-background-color: linear-gradient(from 0% 0% to 100% 100%, #2ecc71 0%, #27ae60 100%);
    -fx-effect: dropshadow(gaussian, rgba(46, 204, 113, 0.6), 12, 0, 0, 5);
    -fx-scale-x: 1.05;
    -fx-scale-y: 1.05;
}

/* ========================================
   BILLING & RECEIPT STYLES
   ======================================== */

/* Bill/Receipt Paper Style */
.bill-receipt-container {
    -fx-background-color: transparent;
    -fx-alignment: center;
}

.bill-paper {
    -fx-background-color: #fffef5;
    -fx-background-radius: 5px;
    -fx-border-color: #ddd;
    -fx-border-width: 1px;
    -fx-border-radius: 5px;
    -fx-effect: dropshadow(gaussian, rgba(0, 0, 0, 0.2), 15, 0, 3, 5);
    -fx-min-width: 380px;
    -fx-max-width: 420px;
    -fx-font-family: "Consolas", "Courier New", monospace;
}

.bill-store-name {
    -fx-font-size: 22px;
    -fx-font-weight: bold;
    -fx-text-fill: #2c3e50;
    -fx-padding: 0 0 5px 0;
}

.bill-receipt-title {
    -fx-font-size: 14px;
    -fx-font-weight: bold;
    -fx-text-fill: #555;
    -fx-padding: 5px 0;
}

.bill-date {
    -fx-font-size: 11px;
    -fx-text-fill: #888;
    -fx-padding: 2px 0 8px 0;
}

.bill-divider {
    -fx-font-size: 10px;
    -fx-text-fill: #aaa;
    -fx-padding: 3px 0;
}

.bill-dotted-line {
    -fx-font-size: 10px;
    -fx-text-fill: #bbb;
    -fx-padding: 2px 0;
}

.bill-header-row {
    -fx-padding: 8px 0 5px 0;
}

.bill-header-label {
    -fx-font-size: 12px;
    -fx-font-weight: bold;
    -fx-text-fill: #333;
    -fx-min-width: 180px;
}

.bill-header-label-small {
    -fx-font-size: 12px;
    -fx-font-weight: bold;
    -fx-text-fill: #333;
    -fx-min-width: 50px;
    -fx-alignment: center;
}

.bill-header-label-right {
    -fx-font-size: 12px;
    -fx-font-weight: bold;
    -fx-text-fill: #333;
    -fx-min-width: 100px;
    -fx-alignment: center-right;
}

.bill-items-section {
    -fx-padding: 5px 0;
    -fx-min-height: 20px;
}

.bill-item-row {
    -fx-padding: 3px 0;
}

.bill-item-name {
    -fx-font-size: 11px;
    -fx-text-fill: #444;
    -fx-min-width: 180px;
    -fx-max-width: 180px;
}

.bill-item-qty {
    -fx-font-size: 11px;
    -fx-text-fill: #666;
    -fx-min-width: 50px;
    -fx-alignment: center;
}

.bill-item-price {
    -fx-font-size: 11px;
    -fx-text-fill: #444;
    -fx-min-width: 100px;
    -fx-alignment: center-right;
}

.bill-subtotal-row {
    -fx-padding: 8px 0 5px 0;
}

.bill-info-row {
    -fx-padding: 3px 0;
}

.bill-label {
    -fx-font-size: 12px;
    -fx-text-fill: #555;
}

.bill-value {
    -fx-font-size: 12px;
    -fx-font-weight: bold;
    -fx-text-fill: #333;
}

.bill-value-small {
    -fx-font-size: 12px;
    -fx-text-fill: #555;
}

.bill-total-row {
    -fx-padding: 10px 0;
    -fx-background-color: #f8f4e8;
    -fx-background-radius: 5px;
}

.bill-grand-total-label {
    -fx-font-size: 16px;
    -fx-font-weight: bold;
    -fx-text-fill: #2c3e50;
    -fx-padding: 0 0 0 10px;
}

.bill-grand-total-value {
    -fx-font-size: 18px;
    -fx-font-weight: bold;
    -fx-text-fill: #e74c3c;
    -fx-padding: 0 10px 0 0;
}

.bill-thank-you {
    -fx-font-size: 12px;
    -fx-font-style: italic;
    -fx-text-fill: #27ae60;
    -fx-padding: 10px 0 3px 0;
}

.bill-contact {
    -fx-font-size: 10px;
    -fx-text-fill: #888;
    -fx-padding: 0 0 5px 0;
}

.bill-buttons {
    -fx-padding: 10px 0 0 0;
}

.bill-clear-btn {
    -fx-background-color: #e74c3c;
    -fx-text-fill: white;
    -fx-font-size: 12px;
    -fx-font-weight: bold;
    -fx-padding: 10px 20px;
    -fx-background-radius: 20px;
    -fx-cursor: hand;
    -fx-effect: dropshadow(gaussian, rgba(231, 76, 60, 0.3), 8, 0, 0, 2);
}

.bill-clear-btn:hover {
    -fx-background-color: #c0392b;
    -fx-effect: dropshadow(gaussian, rgba(192, 57, 43, 0.5), 12, 0, 0, 4);
    -fx-scale-x: 1.03;
    -fx-scale-y: 1.03;
}

.bill-checkout-btn {
    -fx-background-color: linear-gradient(from 0% 0% to 100% 100%, #27ae60 0%, #2ecc71 100%);
    -fx-text-fill: white;
    -fx-font-size: 13px;
    -fx-font-weight: bold;
    -fx-padding: 10px 25px;
    -fx-background-radius: 20px;
    -fx-cursor: hand;
    -fx-effect: dropshadow(gaussian, rgba(39, 174, 96, 0.4), 10, 0, 0, 3);
}

.bill-checkout-btn:hover {
    -fx-background-color: linear-gradient(from 0% 0% to 100% 100%, #2ecc71 0%, #58d68d 100%);
    -fx-effect: dropshadow(gaussian, rgba(46, 204, 113, 0.6), 15, 0, 0, 5);
    -fx-scale-x: 1.03;
    -fx-scale-y: 1.03;
}

/* Bill Items Scroll */
.bill-items-scroll {
    -fx-background-color: transparent;
    -fx-background: transparent;
    -fx-border-color: transparent;
}

.bill-items-scroll .viewport {
    -fx-background-color: transparent;
}

.bill-items-scroll .scroll-bar:vertical {
    -fx-background-color: transparent;
    -fx-pref-width: 6px;
}

.bill-items-scroll .scroll-bar:vertical .track {
    -fx-background-color: #e0ddd5;
    -fx-background-radius: 3px;
}

.bill-items-scroll .scroll-bar:vertical .thumb {
    -fx-background-color: #aaa;
    -fx-background-radius: 3px;
}

.bill-items-scroll .scroll-bar:vertical .thumb:hover {
    -fx-background-color: #888;
}

/* Bill Item Remove Button */
.bill-item-remove-btn {
    -fx-background-color: #e74c3c;
    -fx-text-fill: white;
    -fx-font-size: 10px;
    -fx-font-weight: bold;
    -fx-min-width: 22px;
    -fx-max-width: 22px;
    -fx-min-height: 22px;
    -fx-max-height: 22px;
    -fx-background-radius: 50%;
    -fx-cursor: hand;
    -fx-padding: 0;
}

.bill-item-remove-btn:hover {
    -fx-background-color: #c0392b;
    -fx-scale-x: 1.1;
    -fx-scale-y: 1.1;
}

/* Cart Page Background */
.cart-page-bg {
    -fx-background-color: #f5f5f5;
}

/* ==================== ADD PRODUCT PANEL STYLES ==================== */

.admin-add-btn {
    -fx-background-color: linear-gradient(from 0% 0% to 100% 100%, #27ae60 0%, #2ecc71 100%);
    -fx-text-fill: white;
    -fx-font-size: 13px;
    -fx-font-weight: bold;
    -fx-background-radius: 20px;
    -fx-padding: 10px 20px;
    -fx-cursor: hand;
    -fx-effect: dropshadow(gaussian, rgba(39, 174, 96, 0.4), 10, 0, 0, 3);
}

.admin-add-btn:hover {
    -fx-background-color: linear-gradient(from 0% 0% to 100% 100%, #2ecc71 0%, #58d68d 100%);
    -fx-scale-x: 1.05;
    -fx-scale-y: 1.05;
}

.add-product-panel {
