}

.add-product-header {
    -fx-background-color: linear-gradient(from 0% 0% to 100% 100%, #667eea 0%, #764ba2 100%);
    -fx-background-radius: 18px 18px 0 0;
}

.add-product-header .add-product-title {
    -fx-text-fill: white;
}

.add-product-scroll {
    -fx-background-color: transparent;
    -fx-background: transparent;
    -fx-border-color: transparent;
}

.add-product-scroll > .viewport {
    -fx-background-color: transparent;
}

.add-product-scroll > .scroll-bar:vertical {
    -fx-background-color: #f0f0f0;
