}

.add-product-scroll > .scroll-bar:vertical > .thumb {
    -fx-background-color: #667eea;
    -fx-background-radius: 5px;
}

.add-product-title {
    -fx-font-size: 22px;
    -fx-font-weight: bold;
    -fx-text-fill: #333;
}

.image-preview-box {
    -fx-background-color: #f8f9fa;
    -fx-background-radius: 15px;
    -fx-border-color: #ddd;
    -fx-border-width: 2px;
