}

.choose-image-btn {
    -fx-background-color: #667eea;
    -fx-text-fill: white;
    -fx-font-size: 13px;
    -fx-font-weight: bold;
    -fx-background-radius: 10px;
    -fx-padding: 10px 25px;
    -fx-cursor: hand;
}

.choose-image-btn:hover {
    -fx-background-color: #5568d3;
    -fx-scale-x: 1.03;
    -fx-scale-y: 1.03;
}

.form-label {
    -fx-font-size: 14px;
    -fx-font-weight: bold;
    -fx-text-fill: #333;
}

.form-textfield {
    -fx-background-color: #f8f9fa;
    -fx-background-radius: 10px;
    -fx-border-color: #ddd;
    -fx-border-radius: 10px;
    -fx-border-width: 1px;
    -fx-font-size: 14px;
    -fx-padding: 10px 15px;
}

.form-textfield:focused {
    -fx-border-color: #667eea;
    -fx-border-width: 2px;
}

.form-combobox {
    -fx-background-color: #f8f9fa;
    -fx-background-radius: 10px;
    -fx-border-color: #ddd;
    -fx-border-radius: 10px;
    -fx-border-width: 1px;
    -fx-font-size: 14px;
}

.cancel-btn {
    -fx-background-color: #e74c3c;
    -fx-text-fill: white;
    -fx-font-size: 14px;
    -fx-font-weight: bold;
    -fx-background-radius: 10px;
    -fx-padding: 12px 30px;
    -fx-cursor: hand;
}

.cancel-btn:hover {
    -fx-background-color: #c0392b;
    -fx-scale-x: 1.03;
    -fx-scale-y: 1.03;
}

.submit-btn {
    -fx-background-color: linear-gradient(from 0% 0% to 100% 100%, #27ae60 0%, #2ecc71 100%);
    -fx-text-fill: white;
    -fx-font-size: 14px;
    -fx-font-weight: bold;
    -fx-background-radius: 10px;
    -fx-padding: 12px 30px;
    -fx-cursor: hand;
    -fx-effect: dropshadow(gaussian, rgba(39, 174, 96, 0.4), 10, 0, 0, 3);
}

.submit-btn:hover {
    -fx-background-color: linear-gradient(from 0% 0% to 100% 100%, #2ecc71 0%, #58d68d 100%);
    -fx-scale-x: 1.05;
    -fx-scale-y: 1.05;
}

.add-product-status {
    -fx-font-size: 13px;
    -fx-font-weight: bold;
}

/* Overlay Background - dims the page when panel is open */
.overlay-bg {
    -fx-background-color: rgba(0, 0, 0, 0.5);
}

/* NEW Product Badge */
.product-new-badge {
    -fx-background-color: linear-gradient(from 0% 0% to 100% 100%, #667eea 0%, #764ba2 100%);
    -fx-text-fill: white;
    -fx-font-size: 11px;
    -fx-font-weight: 900;
    -fx-background-radius: 8px;
    -fx-padding: 5px 10px;
    -fx-effect: dropshadow(gaussian, rgba(102, 126, 234, 0.5), 10, 0, 0, 3);
}

/* ==================== STOCK MANAGEMENT PAGE STYLES ==================== */

.stock-topbar {
    -fx-background-color: linear-gradient(from 0% 0% to 100% 100%, #1e3a5f 0%, #2c5282 100%);
    -fx-effect: dropshadow(gaussian, rgba(0, 0, 0, 0.2), 15, 0, 0, 5);
}

.stock-brand {
    -fx-font-size: 26px;
    -fx-font-weight: bold;
    -fx-text-fill: white;
    -fx-effect: dropshadow(gaussian, rgba(0, 0, 0, 0.3), 8, 0, 0, 2);
}

.stock-back-btn {
    -fx-background-color: linear-gradient(from 0% 0% to 100% 100%, #4a5568 0%, #2d3748 100%);
    -fx-text-fill: white;
    -fx-font-size: 14px;
    -fx-font-weight: bold;
    -fx-background-radius: 12px;
    -fx-padding: 10px 20px;
    -fx-cursor: hand;
}

.stock-back-btn:hover {
    -fx-background-color: linear-gradient(from 0% 0% to 100% 100%, #5a6578 0%, #3d4758 100%);
    -fx-scale-x: 1.05;
    -fx-scale-y: 1.05;
}

.stock-scroll {
    -fx-background-color: #f5f7fa;
    -fx-background: #f5f7fa;
}

.stock-page-title {
    -fx-font-size: 28px;
    -fx-font-weight: bold;
    -fx-text-fill: #1a365d;
}

.stock-title-underline {
    -fx-fill: linear-gradient(to right, #1e3a5f 0%, #2c5282 100%);
}

/* Summary Cards */
.stock-summary-card {
    -fx-background-color: white;
    -fx-background-radius: 15px;
    -fx-padding: 20px 40px;
    -fx-effect: dropshadow(gaussian, rgba(0, 0, 0, 0.1), 10, 0, 0, 3);
    -fx-min-width: 150px;
}

.stock-summary-card-green {
    -fx-background-color: linear-gradient(from 0% 0% to 100% 100%, #d4edda 0%, #c3e6cb 100%);
    -fx-background-radius: 15px;
    -fx-padding: 20px 40px;
    -fx-effect: dropshadow(gaussian, rgba(40, 167, 69, 0.2), 10, 0, 0, 3);
    -fx-min-width: 150px;
}

.stock-summary-card-yellow {
    -fx-background-color: linear-gradient(from 0% 0% to 100% 100%, #fff3cd 0%, #ffeaa7 100%);
    -fx-background-radius: 15px;
    -fx-padding: 20px 40px;
    -fx-effect: dropshadow(gaussian, rgba(255, 193, 7, 0.2), 10, 0, 0, 3);
    -fx-min-width: 150px;
}

.stock-summary-card-red {
    -fx-background-color: linear-gradient(from 0% 0% to 100% 100%, #f8d7da 0%, #f5c6cb 100%);
    -fx-background-radius: 15px;
    -fx-padding: 20px 40px;
    -fx-effect: dropshadow(gaussian, rgba(220, 53, 69, 0.2), 10, 0, 0, 3);
    -fx-min-width: 150px;
}

.stock-summary-number {
    -fx-font-size: 36px;
    -fx-font-weight: bold;
    -fx-text-fill: #1a365d;
}

.stock-summary-title {
    -fx-font-size: 14px;
    -fx-font-weight: 600;
    -fx-text-fill: #4a5568;
}

/* Filter Bar */
.stock-filter-bar {
    -fx-background-color: white;
    -fx-background-radius: 12px;
    -fx-effect: dropshadow(gaussian, rgba(0, 0, 0, 0.08), 8, 0, 0, 2);
}

.stock-filter-label {
    -fx-font-size: 14px;
    -fx-font-weight: bold;
    -fx-text-fill: #4a5568;
}

.stock-filter {
    -fx-background-color: #edf2f7;
    -fx-text-fill: #4a5568;
    -fx-font-size: 13px;
    -fx-font-weight: 600;
    -fx-background-radius: 8px;
    -fx-padding: 8px 16px;
    -fx-cursor: hand;
}

.stock-filter:hover {
    -fx-background-color: #e2e8f0;
}

.stock-filter-active {
    -fx-background-color: linear-gradient(from 0% 0% to 100% 100%, #1e3a5f 0%, #2c5282 100%);
    -fx-text-fill: white;
}

/* Stock Table */
.stock-table-header {
    -fx-background-color: linear-gradient(from 0% 0% to 100% 100%, #1e3a5f 0%, #2c5282 100%);
    -fx-background-radius: 10px 10px 0 0;
    -fx-padding: 15px 10px;
}

.stock-header-cell {
    -fx-text-fill: white;
    -fx-font-size: 14px;
    -fx-font-weight: bold;
    -fx-padding: 0 10px;
}

.stock-table-body {
    -fx-background-color: white;
    -fx-background-radius: 0 0 10px 10px;
    -fx-effect: dropshadow(gaussian, rgba(0, 0, 0, 0.1), 8, 0, 0, 2);
}

.stock-row-odd {
    -fx-background-color: #f8fafc;
    -fx-padding: 12px 10px;
}

.stock-row-even {
    -fx-background-color: white;
    -fx-padding: 12px 10px;
}

.stock-row-odd:hover, .stock-row-even:hover {
    -fx-background-color: #e2e8f0;
}

.stock-cell {
    -fx-font-size: 13px;
    -fx-text-fill: #2d3748;
    -fx-padding: 0 10px;
}

.stock-qty-label {
    -fx-font-size: 14px;
    -fx-font-weight: bold;
    -fx-padding: 5px 15px;
    -fx-background-radius: 6px;
}

.stock-qty-ok {
    -fx-background-color: #d4edda;
    -fx-text-fill: #155724;
}

.stock-qty-low {
    -fx-background-color: #fff3cd;
    -fx-text-fill: #856404;
}

.stock-qty-out {
    -fx-background-color: #f8d7da;
    -fx-text-fill: #721c24;
}

.status-ok {
    -fx-text-fill: #28a745;
    -fx-font-weight: bold;
}

.status-low {
    -fx-text-fill: #ffc107;
    -fx-font-weight: bold;
}

.status-out {
    -fx-text-fill: #dc3545;
    -fx-font-weight: bold;
}

.stock-add-btn {
    -fx-background-color: #28a745;
    -fx-text-fill: white;
    -fx-font-size: 12px;
    -fx-font-weight: bold;
    -fx-background-radius: 6px;
    -fx-padding: 5px 12px;
    -fx-cursor: hand;
}

.stock-add-btn:hover {
    -fx-background-color: #218838;
}

.stock-remove-btn {
    -fx-background-color: #dc3545;
    -fx-text-fill: white;
    -fx-font-size: 12px;
    -fx-font-weight: bold;
    -fx-background-radius: 6px;
    -fx-padding: 5px 12px;
    -fx-cursor: hand;
}

.stock-remove-btn:hover {
    -fx-background-color: #c82333;
}

.stock-status {
    -fx-font-size: 14px;
    -fx-text-fill: #4a5568;
    -fx-font-weight: 600;
}

/* ========== SALES POS INTERFACE ========== */

.category-btn {
    -fx-background-color: #e8e8e8;
    -fx-text-fill: #333;
    -fx-font-size: 12;
    -fx-padding: 8px 15px;
    -fx-border-radius: 5;
    -fx-cursor: hand;
}

.category-btn:hover {
    -fx-background-color: #d0d0d0;
}

.category-btn-active {
    -fx-background-color: #3498db;
    -fx-text-fill: white;
    -fx-font-size: 12;
    -fx-padding: 8px 15px;
    -fx-border-radius: 5;
    -fx-cursor: hand;
    -fx-font-weight: bold;
}

.products-scroll {
    -fx-padding: 0;
    -fx-border-color: #ddd;
    -fx-border-radius: 5;
}

.products-grid {
