.product-card:hover {
    -fx-border-color: #3498db;
    -fx-effect: dropshadow(gaussian, rgba(52, 152, 219, 0.3), 10, 0, 0, 3);
}

.cart-section {
    -fx-border-color: #ddd;
    -fx-border-radius: 8;
    -fx-padding: 15;
    -fx-background-color: #f9f9f9;
}

.cart-scroll {
    -fx-border-color: #ddd;
    -fx-border-radius: 5;
}

.cart-summary {
    -fx-border-color: #ddd;
    -fx-border-radius: 5;
    -fx-padding: 10;
    -fx-background-color: #fff;
}

.summary-label {
    -fx-font-size: 12;
    -fx-text-fill: #666;
}

.summary-value {
    -fx-font-size: 12;
    -fx-font-weight: bold;
    -fx-text-fill: #333;
}

.summary-value-total {
    -fx-font-size: 14;
    -fx-font-weight: bold;
    -fx-text-fill: #27ae60;
}

.confirm-btn {
    -fx-background-color: #27ae60;
    -fx-text-fill: white;
    -fx-font-size: 13;
    -fx-font-weight: bold;
    -fx-padding: 10px 20px;
    -fx-border-radius: 5;
    -fx-cursor: hand;
}

.confirm-btn:hover {
    -fx-background-color: #229954;
}

.cancel-btn {
    -fx-background-color: #e74c3c;
    -fx-text-fill: white;
    -fx-font-size: 13;
    -fx-font-weight: bold;
    -fx-padding: 10px 20px;
    -fx-border-radius: 5;
    -fx-cursor: hand;
}

.cancel-btn:hover {
    -fx-background-color: #c0392b;
}

/* Beauty page list-only rows */
.beauty-list-row {
    -fx-background-color: #ffffff;
    -fx-background-radius: 10;
    -fx-border-color: #e7eaf0;
    -fx-border-radius: 10;
    -fx-padding: 14;
}

.beauty-list-row .product-name {
    -fx-font-size: 16px;
    -fx-font-weight: 700;
    -fx-text-fill: #1f2937;
}

.product-id-label {
    -fx-font-size: 12px;
    -fx-text-fill: #6b7280;
    -fx-font-weight: 600;
}

/* ===== Global forced dark theme + bold text ===== */
.root,
.home-page-bg,
.anchor-pane,
.vbox,
.hbox,
.stack-pane,
.border-pane,
.grid-pane,
.tile-pane,
.flow-pane,
.scroll-pane,
.scroll-pane > .viewport,
.table-view,
.list-view,
.tree-view,
.tab-pane .tab-content-area {
    -fx-background-color: #000000;
    -fx-background-image: none;
}

.label,
.text,
.button,
.toggle-button,
.check-box,
.radio-button,
.menu-button,
.hyperlink,
.tab .tab-label,
.table-view .column-header .label,
.table-cell,
.list-cell,
.tree-cell,
.combo-box,
.combo-box-base,
.choice-box,
.text-field,
.password-field,
.text-area,
.spinner .text-field,
.date-picker,
.date-picker .text-field {
    -fx-text-fill: #f5f5f5;
    -fx-font-weight: 700;
}

.text-field,
.password-field,
.text-area,
.combo-box-base,
.choice-box,
.date-picker,
.spinner .text-field {
    -fx-background-color: #111111;
    -fx-border-color: #333333;
}

.chart,
.chart-plot-background,
.chart-content,
.chart-vertical-grid-lines,
.chart-horizontal-grid-lines {
    -fx-background-color: #000000;
}

.axis,
.axis-label,
.axis-tick-mark,
.axis-minor-tick-mark,
.chart-legend-item,
.chart-legend-item-symbol,
.chart-title {
    -fx-text-fill: #f5f5f5;
    -fx-font-weight: 700;
}

/* Explicit dark overrides for login/dashboard classes that were light */
.home-page-bg,
.left-panel,
.right-panel,
.dashboard-header,
.dashboard-main,
.content-card,
.dashboard-side-column .content-card,
.home-card,
.home-status,
.modern-table,
.table-view,
.table-view .column-header-background,
.table-row-cell,
.table-row-cell:odd,
.table-row-cell:even,
.list-cell,
.list-view,
.combo-box-popup .list-view,
.menu-item,
.context-menu {
    -fx-background-color: #000000;
    -fx-background-image: none;
    -fx-border-color: #222222;
}

.subtitle,
.field-label,
.login-title,
.signup-text,
.forgot-link,
.signup-link,
.link-button,
.dashboard-title,
.dashboard-welcome,
.section-title,
.chart-placeholder,
.activity-item,
.cart-status-label,
.product-id-label {
    -fx-text-fill: #f5f5f5;
    -fx-font-weight: 700;
}

.text-field,
.password-field,
.text-area,
.table-view,
.list-view,
.combo-box,
.combo-box-base,
.date-picker,
.date-picker .text-field,
.spinner .text-field,
.choice-box {
    -fx-control-inner-background: #111111;
    -fx-background-color: #111111;
    -fx-text-fill: #f5f5f5;
    -fx-prompt-text-fill: #9ca3af;
    -fx-border-color: #333333;
}

.table-view .column-header,
.table-view .filler,
.table-view .corner {
    -fx-background-color: #111111;
}

/* ===== Home Add Product Overlay ===== */
.product-modal-overlay {
    -fx-background-color: rgba(0, 0, 0, 0.62);
}

.product-modal-panel {
    -fx-background-color: #111111;
    -fx-background-radius: 10;
    -fx-border-color: #333333;
    -fx-border-radius: 10;
    -fx-padding: 14;
}

.product-close-btn {
    -fx-background-color: transparent;
    -fx-text-fill: #f5f5f5;
    -fx-font-size: 16px;
    -fx-font-weight: 700;
    -fx-cursor: hand;
}

.product-close-btn:hover {
    -fx-font-weight: 900;
    -fx-text-fill: #ffffff;
    -fx-scale-x: 1.08;
    -fx-scale-y: 1.08;
}

.product-form-label {
    -fx-text-fill: #f5f5f5;
    -fx-font-size: 14px;
    -fx-font-weight: 700;
}

.product-form-field {
    -fx-background-color: #0f0f0f;
    -fx-text-fill: #f5f5f5;
    -fx-font-weight: 700;
    -fx-border-color: #333333;
    -fx-border-radius: 4;
    -fx-background-radius: 4;
}

.product-image-preview {
    -fx-border-color: #3a3a3a;
    -fx-border-width: 1;
    -fx-background-color: #0c0c0c;
}

.product-image-label {
    -fx-text-fill: #d1d5db;
    -fx-font-size: 11px;
    -fx-font-weight: 700;
}

.product-action-btn {
    -fx-text-fill: #f5f5f5;
    -fx-font-weight: 800;
    -fx-font-size: 14px;
    -fx-padding: 8 14;
    -fx-background-radius: 4;
    -fx-cursor: hand;
}

.product-action-add {
    -fx-background-color: #1f9d72;
}

.product-action-update {
    -fx-background-color: #1b8f6a;
}

.product-action-clear {
    -fx-background-color: #177f5e;
}

.product-action-delete {
    -fx-background-color: #146f53;
}

.product-action-import {
    -fx-background-color: #0f8b68;
}

/* Keep all typed input fields dark even on focus/hover */
.text-input,
.text-field,
.password-field,
.text-area,
.combo-box-base,
.date-picker,
.spinner .text-field,
.choice-box {
    -fx-control-inner-background: #111111;
    -fx-background-color: #111111;
    -fx-text-fill: #f5f5f5;
    -fx-prompt-text-fill: #9ca3af;
    -fx-border-color: #333333;
}

.text-input:focused,
.text-input:hover,
.text-field:focused,
.text-field:hover,
.password-field:focused,
.password-field:hover,
.text-area:focused,
.text-area:hover,
.combo-box-base:focused,
.combo-box-base:hover,
.date-picker:focused,
.date-picker:hover,
.spinner .text-field:focused,
.spinner .text-field:hover {
    -fx-control-inner-background: #111111;
    -fx-background-color: #111111;
    -fx-border-color: #4b5563;
    -fx-text-fill: #f5f5f5;
}

.text-area .content {
    -fx-background-color: #111111;
}

/* Compact button sizing so labels fit fully across pages */
.button {
    -fx-font-size: 14px;
    -fx-padding: 8 14;
    -fx-alignment: center;
}

.due-toggle-black {
    -fx-background-color: #000000;
    -fx-text-fill: #f5f5f5;
    -fx-border-color: #3f3f46;
    -fx-border-radius: 8;
    -fx-background-radius: 8;
    -fx-padding: 6 12;
}

.due-toggle-black:hover {
    -fx-background-color: #111111;
    -fx-border-color: #52525b;
}

.due-toggle-black:selected {
    -fx-background-color: #18181b;
    -fx-border-color: #71717a;
}

/* Root styling - Clean background */
.root {
    -fx-background-color: #f0f2f5;
}

/* Home page background image */
.home-page-bg {
    -fx-background-image: url("../../../background/istockphoto-1423573676-170667a%20%281%29%20-%20Copy.png");
    -fx-background-position: center center;
    -fx-background-repeat: no-repeat;
    -fx-background-size: cover;
    -fx-background-color: #f0f2f5;
}

/* Left Panel - solid color (JavaFX 21 CSS-safe) */
.left-panel {
    /* JavaFX CSS doesn't accept CSS4 linear-gradient() in -fx-background-color */
    -fx-background-color: #2e7d32;
    -fx-effect: dropshadow(gaussian, rgba(0, 0, 0, 0.15), 25, 0, 5, 0);
}

/* Circle decorations */
.circle-decoration {
    -fx-opacity: 0.3;
    -fx-effect: dropshadow(gaussian, rgba(255, 255, 255, 0.2), 30, 0, 0, 0);
}

/* Welcome text on left panel */
.welcome-text {
    -fx-text-fill: #ffffff;
    -fx-font-weight: bold;
    -fx-effect: dropshadow(gaussian, rgba(0, 0, 0, 0.2), 10, 0, 0, 3);
}

.welcome-text-large {
    -fx-text-fill: #ffffff;
    -fx-font-weight: bold;
    -fx-effect: dropshadow(gaussian, rgba(0, 0, 0, 0.3), 15, 0, 0, 5);
}

.welcome-subtitle {
    -fx-text-fill: rgba(255, 255, 255, 0.92);
    -fx-font-style: italic;
    -fx-font-weight: 700;
    -fx-letter-spacing: 0.4px;
    -fx-effect: dropshadow(gaussian, rgba(0, 0, 0, 0.22), 10, 0, 0, 3);
}

/* Right Panel - White card with shadow */
.right-panel {
    -fx-background-color: #1a1a1a;
    -fx-background-radius: 20px;
    -fx-effect: dropshadow(gaussian, rgba(0, 0, 0, 0.3), 30, 0, 0, 10);
}

/* Login title */
.login-title {
    /* gradient text fill isn't supported reliably in JavaFX; use solid */
    -fx-text-fill: #4caf50;
    -fx-font-weight: bold;
    -fx-effect: dropshadow(gaussian, rgba(76, 175, 80, 0.2), 8, 0, 0, 3);
}

/* Subtitle */
.subtitle {
    -fx-text-fill: #aaaaaa;
}

/* Decorative line under subtitle */
.decorative-line {
    -fx-fill: linear-gradient(to right, #4caf50 0%, #2e7d32 100%);
    -fx-effect: dropshadow(gaussian, rgba(76, 175, 80, 0.4), 8, 0, 0, 2);
}

/* Field labels */
.field-label {
    -fx-text-fill: #e0e0e0;
    -fx-font-weight: bold;
}

/* Modern TextField styling */
.modern-field {
    -fx-background-color: #2c2c2c;
    -fx-background-radius: 12px;
    -fx-border-color: #444444;
    -fx-border-radius: 12px;
    -fx-border-width: 2px;
    -fx-padding: 12px 18px;
    -fx-font-size: 14px;
    -fx-text-fill: #ffffff;
    -fx-prompt-text-fill: #888888;
    -fx-effect: dropshadow(gaussian, rgba(0, 0, 0, 0.1), 10, 0, 0, 2);
}

.modern-field:focused {
    -fx-border-color: #4caf50;
    -fx-background-color: #252525;
    -fx-effect: dropshadow(gaussian, rgba(76, 175, 80, 0.3), 15, 0, 0, 3);
}

.modern-field:hover {
    -fx-border-color: #66bb6a;
    -fx-background-color: #252525;
}

/* TextField specific */
.text-field {
    -fx-background-color: #2c2c2c;
    -fx-background-radius: 12px;
    -fx-border-color: #444444;
    -fx-border-radius: 12px;
    -fx-border-width: 2px;
    -fx-padding: 12px 18px;
    -fx-font-size: 14px;
    -fx-text-fill: #ffffff;
    -fx-prompt-text-fill: #888888;
    -fx-effect: dropshadow(gaussian, rgba(0, 0, 0, 0.1), 10, 0, 0, 2);
}

.text-field:focused {
    -fx-border-color: #4caf50;
    -fx-background-color: #252525;
    -fx-effect: dropshadow(gaussian, rgba(76, 175, 80, 0.3), 15, 0, 0, 3);
}

.text-field:hover {
    -fx-border-color: #66bb6a;
    -fx-background-color: #252525;
}

/* PasswordField styling */
.password-field {
    -fx-background-color: #2c2c2c;
    -fx-background-radius: 12px;
    -fx-border-color: #444444;
    -fx-border-radius: 12px;
    -fx-border-width: 2px;
    -fx-padding: 12px 18px;
    -fx-font-size: 14px;
    -fx-text-fill: #ffffff;
    -fx-prompt-text-fill: #888888;
    -fx-effect: dropshadow(gaussian, rgba(0, 0, 0, 0.1), 10, 0, 0, 2);
}

.password-field:focused {
    -fx-border-color: #4caf50;
    -fx-background-color: #252525;
    -fx-effect: dropshadow(gaussian, rgba(76, 175, 80, 0.3), 15, 0, 0, 3);
}

.password-field:hover {
    -fx-border-color: #66bb6a;
    -fx-background-color: #252525;
}

/* Modern Login Button (solid color for JavaFX CSS parser compatibility) */
.login-button {
    -fx-background-color: #2e7d32;
    -fx-text-fill: white;
    -fx-font-size: 16px;
    -fx-font-weight: bold;
    -fx-background-radius: 25px;
    -fx-padding: 15px 40px;
    -fx-cursor: hand;
    -fx-effect: dropshadow(gaussian, rgba(46, 125, 50, 0.5), 20, 0, 0, 5);
}

.login-button:hover {
    -fx-background-color: #1b5e20;
    -fx-scale-x: 1.05;
    -fx-scale-y: 1.05;
    -fx-effect: dropshadow(gaussian, rgba(46, 125, 50, 0.7), 25, 0, 0, 7);
}

.login-button:pressed {
    -fx-background-color: #0d3b10;
    -fx-scale-x: 0.98;
    -fx-scale-y: 0.98;
    -fx-effect: dropshadow(gaussian, rgba(46, 125, 50, 0.4), 15, 0, 0, 3);
}

/* General Button styling */
.button {
    -fx-background-color: #4caf50;
    -fx-text-fill: white;
    -fx-font-size: 16px;
    -fx-font-weight: bold;
    -fx-background-radius: 25px;
    -fx-padding: 15px 40px;
    -fx-cursor: hand;
    -fx-effect: dropshadow(gaussian, rgba(76, 175, 80, 0.35), 20, 0, 0, 5);
}

.button:hover {
    -fx-background-color: #388e3c;
    -fx-scale-x: 1.05;
    -fx-scale-y: 1.05;
    -fx-effect: dropshadow(gaussian, rgba(76, 175, 80, 0.5), 25, 0, 0, 7);
}

/* Forgot password link */
.forgot-link {
    -fx-text-fill: #4caf50;
    -fx-font-size: 13px;
    -fx-underline: false;
    -fx-padding: 0;
}

.forgot-link:hover {
    -fx-text-fill: #81c784;
    -fx-underline: true;
}

/* Signup text and link */
.signup-text {
    -fx-text-fill: #aaaaaa;
}

.signup-link {
    -fx-text-fill: #4caf50;
    -fx-font-weight: bold;
    -fx-underline: false;
}

.signup-link:hover {
    -fx-text-fill: #81c784;
    -fx-underline: true;
}

/* Link button styling for signup page */
.link-button {
    -fx-background-color: transparent;
    -fx-text-fill: #667eea;
    -fx-padding: 0;
    -fx-font-size: 13px;
    -fx-font-weight: bold;
    -fx-border-width: 0;
    -fx-underline: false;
}

.link-button:hover {
    -fx-text-fill: #764ba2;
    -fx-underline: true;
    -fx-cursor: hand;
}

.link-button:pressed {
    -fx-text-fill: #542d72;
    -fx-scale-x: 0.95;
    -fx-scale-y: 0.95;
}

/* Hyperlink general styling */
.hyperlink {
    -fx-text-fill: #667eea;
    -fx-underline: false;
    -fx-font-size: 13px;
    -fx-font-weight: 600;
}

.hyperlink:hover {
    -fx-text-fill: #764ba2;
    -fx-underline: true;
    -fx-effect: dropshadow(gaussian, rgba(118, 75, 162, 0.4), 5, 0, 0, 0);
}

/* Label general styling */
.label {
    -fx-text-fill: #2d3748;
    -fx-font-family: "Segoe UI", Arial, sans-serif;
}

/* Error label styling */
.error-label {
    -fx-text-fill: #e74c3c;
    -fx-font-size: 12px;
    -fx-font-weight: bold;
}

/* Success label styling */
.success-label {
    -fx-text-fill: #27ae60;
    -fx-font-size: 12px;
    -fx-font-weight: bold;
}

/* ===== Home page styles ===== */
.home-topbar {
    -fx-background-color: #111827;
}

.home-brand {
    -fx-text-fill: white;
    -fx-font-size: 20px;
    -fx-font-weight: 800;
}

.home-logout {
    -fx-background-color: #ef4444;
    -fx-text-fill: white;
    -fx-font-weight: bold;
    -fx-background-radius: 12px;
    -fx-padding: 8px 14px;
}

.home-hero {
    -fx-background-color: #667eea;
    -fx-background-radius: 18px;
    -fx-effect: dropshadow(gaussian, rgba(0, 0, 0, 0.14), 16, 0, 0, 6);
}

.home-title {
    -fx-text-fill: white;
    -fx-font-size: 26px;
    -fx-font-weight: 800;
}

.home-subtitle {
    -fx-text-fill: rgba(255,255,255,0.92);
    -fx-font-size: 14px;
}

.home-section-title {
    -fx-text-fill: #111827;
    -fx-font-size: 16px;
    -fx-font-weight: 800;
}

.home-card {
    -fx-background-color: white;
    -fx-text-fill: #111827;
    -fx-font-size: 15px;
    -fx-font-weight: 800;
    -fx-background-radius: 16px;
    -fx-border-color: #e5e7eb;
    -fx-border-radius: 16px;
    -fx-border-width: 2px;
    -fx-effect: dropshadow(gaussian, rgba(0, 0, 0, 0.08), 12, 0, 0, 4);
}

.home-card:hover {
    -fx-border-color: #667eea;
    -fx-translate-y: -2px;
}

.home-status {
    -fx-text-fill: #1f2937;
    -fx-font-size: 13px;
    -fx-font-weight: 700;
    -fx-background-color: #e5edff;
    -fx-background-radius: 10px;
    -fx-padding: 8px 10px;
}

/* Search bar in home page */
.home-search {
    -fx-background-color: rgba(255,255,255,0.10);
    -fx-background-radius: 12px;
    -fx-border-color: rgba(255,255,255,0.18);
    -fx-border-radius: 12px;
    -fx-border-width: 1px;
    -fx-text-fill: white;
    -fx-prompt-text-fill: rgba(255,255,255,0.65);
    -fx-padding: 10px 14px;
    -fx-font-size: 13px;
}

.home-search:focused {
    -fx-border-color: rgba(255,255,255,0.35);
    -fx-background-color: rgba(255,255,255,0.14);
}

/* User label in home page */
.home-user {
    -fx-text-fill: rgba(255,255,255,0.92);
    -fx-font-size: 13px;
    -fx-font-weight: 700;
}

/* Circular profile button */
.profile-circle {
    -fx-background-color: rgba(255,255,255,0.2);
    -fx-background-radius: 50%;
    -fx-pref-width: 40px;
    -fx-pref-height: 40px;
    -fx-min-width: 40px;
    -fx-min-height: 40px;
    -fx-max-width: 40px;
    -fx-max-height: 40px;
    -fx-cursor: hand;
    -fx-effect: dropshadow(gaussian, rgba(0, 0, 0, 0.15), 8, 0, 0, 2);
}

.profile-circle:hover {
    -fx-background-color: rgba(255,255,255,0.3);
    -fx-effect: dropshadow(gaussian, rgba(0, 0, 0, 0.25), 10, 0, 0, 3);
}

/* Call to Action buttons in home page */
.home-cta {
    -fx-background-color: #111827;
    -fx-text-fill: white;
    -fx-font-weight: 800;
    -fx-background-radius: 12px;
    -fx-padding: 10px 16px;
}

.home-cta:hover {
    -fx-background-color: #0b1220;
}

.home-cta-secondary {
    -fx-background-color: rgba(255,255,255,0.22);
    -fx-text-fill: white;
    -fx-font-weight: 800;
    -fx-background-radius: 12px;
    -fx-padding: 10px 16px;
    -fx-effect: none;
}

.home-cta-secondary:hover {
    -fx-background-color: rgba(255,255,255,0.30);
}

/* Offer tiles in home page */
.home-tile {
    -fx-background-color: #111827;
    -fx-text-fill: white;
    -fx-font-size: 14px;
    -fx-font-weight: 800;
    -fx-background-radius: 16px;
    -fx-padding: 14px 18px;
    -fx-effect: dropshadow(gaussian, rgba(0, 0, 0, 0.14), 14, 0, 0, 6);
}

.home-tile:hover {
    -fx-background-color: #0b1220;
    -fx-translate-y: -2px;
}

/* ===== Fashion page styles ===== */

/* Fashion page topbar with gradient */
.fashion-topbar {
    -fx-background-color: linear-gradient(to right, #667eea 0%, #764ba2 100%);
    -fx-effect: dropshadow(gaussian, rgba(0, 0, 0, 0.2), 15, 0, 0, 5);
}

.fashion-brand {
    -fx-text-fill: white;
    -fx-font-size: 24px;
    -fx-font-weight: 900;
    -fx-effect: dropshadow(gaussian, rgba(0, 0, 0, 0.3), 8, 0, 0, 2);
}

.fashion-back-btn {
    -fx-background-color: rgba(255, 255, 255, 0.25);
    -fx-text-fill: white;
    -fx-font-weight: 800;
    -fx-font-size: 14px;
    -fx-background-radius: 12px;
    -fx-padding: 10px 20px;
    -fx-border-color: rgba(255, 255, 255, 0.3);
    -fx-border-radius: 12px;
    -fx-border-width: 2px;
    -fx-effect: dropshadow(gaussian, rgba(0, 0, 0, 0.15), 8, 0, 0, 3);
}

.fashion-back-btn:hover {
    -fx-background-color: rgba(255, 255, 255, 0.35);
    -fx-border-color: rgba(255, 255, 255, 0.5);
    -fx-scale-x: 1.05;
    -fx-scale-y: 1.05;
}

.fashion-back-btn:pressed {
    -fx-background-color: rgba(255, 255, 255, 0.2);
    -fx-scale-x: 0.98;
    -fx-scale-y: 0.98;
}

.fashion-page-title {
    -fx-text-fill: #111827;
    -fx-font-size: 28px;
    -fx-font-weight: 900;
    -fx-effect: dropshadow(gaussian, rgba(0, 0, 0, 0.1), 5, 0, 0, 2);
}

.fashion-title-underline {
    -fx-fill: linear-gradient(to right, #667eea 0%, #764ba2 100%);
    -fx-arc-width: 4;
    -fx-arc-height: 4;
}

.fashion-filter-bar {
    -fx-background-color: white;
    -fx-background-radius: 15px;
    -fx-effect: dropshadow(gaussian, rgba(0, 0, 0, 0.08), 12, 0, 0, 4);
}

.fashion-filter-label {
    -fx-text-fill: #374151;
    -fx-font-size: 15px;
    -fx-font-weight: 800;
}

.fashion-filter {
    -fx-background-color: #f3f4f6;
    -fx-text-fill: #374151;
    -fx-font-size: 14px;
    -fx-font-weight: 700;
    -fx-background-radius: 12px;
    -fx-padding: 10px 20px;
    -fx-border-color: transparent;
    -fx-border-radius: 12px;
    -fx-border-width: 2px;
    -fx-effect: dropshadow(gaussian, rgba(0, 0, 0, 0.05), 6, 0, 0, 2);
}

.fashion-filter:hover {
    -fx-background-color: #e5e7eb;
    -fx-border-color: #d1d5db;
    -fx-scale-x: 1.05;
    -fx-scale-y: 1.05;
}

.fashion-filter-active {
    -fx-background-color: linear-gradient(to right, #667eea 0%, #764ba2 100%);
    -fx-text-fill: white;
    -fx-border-color: transparent;
    -fx-effect: dropshadow(gaussian, rgba(102, 126, 234, 0.4), 10, 0, 0, 4);
}

.fashion-filter-active:hover {
    -fx-background-color: linear-gradient(to right, #5568d3 0%, #653a8a 100%);
    -fx-scale-x: 1.05;
    -fx-scale-y: 1.05;
}

/* Product Cards - Enhanced Design */
.product-card {
    -fx-background-color: white;
    -fx-background-radius: 16px;
    -fx-border-color: #e5e7eb;
    -fx-border-radius: 16px;
    -fx-border-width: 2px;
    -fx-effect: dropshadow(gaussian, rgba(0, 0, 0, 0.1), 15, 0, 0, 5);
}

.product-card:hover {
    -fx-border-color: #667eea;
    -fx-effect: dropshadow(gaussian, rgba(102, 126, 234, 0.4), 20, 0, 0, 8);
    -fx-translate-y: -5;
}

/* Clickable Product Card */
.clickable-card {
    -fx-cursor: hand;
}

.clickable-card:hover {
    -fx-scale-x: 1.03;
    -fx-scale-y: 1.03;
    -fx-border-color: #667eea;
    -fx-effect: dropshadow(gaussian, rgba(102, 126, 234, 0.5), 25, 0, 0, 10);
}

/* Product image placeholder with gradient */
.product-image {
    -fx-background-color: linear-gradient(to bottom right, #f3f4f6 0%, #e5e7eb 100%);
    -fx-background-radius: 14px 14px 0 0;
    -fx-border-color: #e5e7eb;
    -fx-border-radius: 14px 14px 0 0;
    -fx-border-width: 0 0 2px 0;
}

.product-name {
    -fx-text-fill: #111827;
    -fx-font-size: 15px;
    -fx-font-weight: 700;
