    -fx-background-color: linear-gradient(to bottom right, #22c55e 0%, #16a34a 100%);
    -fx-background-radius: 16;
    -fx-effect: dropshadow(gaussian, rgba(34, 197, 94, 0.4), 20, 0.2, 0, 5);
}

.stat-card-blue {
    -fx-background-color: linear-gradient(to bottom right, #38bdf8 0%, #2563eb 100%);
    -fx-background-radius: 16;
    -fx-effect: dropshadow(gaussian, rgba(59, 130, 246, 0.4), 20, 0.2, 0, 5);
}

.stat-card-red {
    -fx-background-color: linear-gradient(to bottom right, #f97316 0%, #ef4444 100%);
    -fx-background-radius: 16;
    -fx-effect: dropshadow(gaussian, rgba(249, 115, 22, 0.38), 20, 0.2, 0, 5);
}

.stat-card-orange {
    -fx-background-color: linear-gradient(to bottom right, #f59e0b 0%, #f97316 100%);
    -fx-background-radius: 16;
    -fx-effect: dropshadow(gaussian, rgba(245, 158, 11, 0.4), 20, 0.2, 0, 5);
