.stat-label {
    -fx-font-size: 14px;
    -fx-text-fill: rgba(255, 255, 255, 0.93);
    -fx-font-weight: 700;
}

.stat-value {
    -fx-font-size: 34px;
    -fx-text-fill: #ffffff;
    -fx-font-weight: 900;
}

/* Action Buttons */
.dashboard-action-row {
