    -fx-background-radius: 10px;
    -fx-border-color: #ddd;
    -fx-border-radius: 10px;
    -fx-border-width: 1px;
    -fx-font-size: 14px;
}

.cancel-btn {
    -fx-background-color: #e74c3c;
    -fx-text-fill: white;
    -fx-font-size: 14px;
    -fx-font-weight: bold;
    -fx-background-radius: 10px;
    -fx-padding: 12px 30px;
    -fx-cursor: hand;
}

.cancel-btn:hover {
    -fx-background-color: #c0392b;
    -fx-scale-x: 1.03;
    -fx-scale-y: 1.03;
}

.submit-btn {
    -fx-background-color: linear-gradient(from 0% 0% to 100% 100%, #27ae60 0%, #2ecc71 100%);
    -fx-text-fill: white;
    -fx-font-size: 14px;
    -fx-font-weight: bold;
    -fx-background-radius: 10px;
    -fx-padding: 12px 30px;
    -fx-cursor: hand;
    -fx-effect: dropshadow(gaussian, rgba(39, 174, 96, 0.4), 10, 0, 0, 3);
}

.submit-btn:hover {
    -fx-background-color: linear-gradient(from 0% 0% to 100% 100%, #2ecc71 0%, #58d68d 100%);
    -fx-scale-x: 1.05;
    -fx-scale-y: 1.05;
}

.add-product-status {
    -fx-font-size: 13px;
    -fx-font-weight: bold;
}

/* Overlay Background - dims the page when panel is open */
.overlay-bg {
    -fx-background-color: rgba(0, 0, 0, 0.5);
}

/* NEW Product Badge */
.product-new-badge {
    -fx-background-color: linear-gradient(from 0% 0% to 100% 100%, #667eea 0%, #764ba2 100%);
    -fx-text-fill: white;
    -fx-font-size: 11px;
    -fx-font-weight: 900;
    -fx-background-radius: 8px;
    -fx-padding: 5px 10px;
    -fx-effect: dropshadow(gaussian, rgba(102, 126, 234, 0.5), 10, 0, 0, 3);
}

/* ==================== STOCK MANAGEMENT PAGE STYLES ==================== */

.stock-topbar {
    -fx-background-color: linear-gradient(from 0% 0% to 100% 100%, #1e3a5f 0%, #2c5282 100%);
    -fx-effect: dropshadow(gaussian, rgba(0, 0, 0, 0.2), 15, 0, 0, 5);
}

.stock-brand {
    -fx-font-size: 26px;
    -fx-font-weight: bold;
    -fx-text-fill: white;
    -fx-effect: dropshadow(gaussian, rgba(0, 0, 0, 0.3), 8, 0, 0, 2);
}

.stock-back-btn {
    -fx-background-color: linear-gradient(from 0% 0% to 100% 100%, #4a5568 0%, #2d3748 100%);
    -fx-text-fill: white;
    -fx-font-size: 14px;
    -fx-font-weight: bold;
    -fx-background-radius: 12px;
    -fx-padding: 10px 20px;
    -fx-cursor: hand;
}

.stock-back-btn:hover {
    -fx-background-color: linear-gradient(from 0% 0% to 100% 100%, #5a6578 0%, #3d4758 100%);
    -fx-scale-x: 1.05;
    -fx-scale-y: 1.05;
}

.stock-scroll {
    -fx-background-color: #f5f7fa;
    -fx-background: #f5f7fa;
}

.stock-page-title {
    -fx-font-size: 28px;
    -fx-font-weight: bold;
    -fx-text-fill: #1a365d;
}

.stock-title-underline {
    -fx-fill: linear-gradient(to right, #1e3a5f 0%, #2c5282 100%);
}

/* Summary Cards */
.stock-summary-card {
    -fx-background-color: white;
    -fx-background-radius: 15px;
    -fx-padding: 20px 40px;
    -fx-effect: dropshadow(gaussian, rgba(0, 0, 0, 0.1), 10, 0, 0, 3);
    -fx-min-width: 150px;
}

.stock-summary-card-green {
    -fx-background-color: linear-gradient(from 0% 0% to 100% 100%, #d4edda 0%, #c3e6cb 100%);
    -fx-background-radius: 15px;
    -fx-padding: 20px 40px;
    -fx-effect: dropshadow(gaussian, rgba(40, 167, 69, 0.2), 10, 0, 0, 3);
    -fx-min-width: 150px;
}

.stock-summary-card-yellow {
    -fx-background-color: linear-gradient(from 0% 0% to 100% 100%, #fff3cd 0%, #ffeaa7 100%);
    -fx-background-radius: 15px;
    -fx-padding: 20px 40px;
    -fx-effect: dropshadow(gaussian, rgba(255, 193, 7, 0.2), 10, 0, 0, 3);
    -fx-min-width: 150px;
}

.stock-summary-card-red {
    -fx-background-color: linear-gradient(from 0% 0% to 100% 100%, #f8d7da 0%, #f5c6cb 100%);
    -fx-background-radius: 15px;
    -fx-padding: 20px 40px;
    -fx-effect: dropshadow(gaussian, rgba(220, 53, 69, 0.2), 10, 0, 0, 3);
    -fx-min-width: 150px;
}

.stock-summary-number {
    -fx-font-size: 36px;
    -fx-font-weight: bold;
    -fx-text-fill: #1a365d;
}

.stock-summary-title {
    -fx-font-size: 14px;
    -fx-font-weight: 600;
    -fx-text-fill: #4a5568;
}

/* Filter Bar */
.stock-filter-bar {
    -fx-background-color: white;
    -fx-background-radius: 12px;
    -fx-effect: dropshadow(gaussian, rgba(0, 0, 0, 0.08), 8, 0, 0, 2);
}

.stock-filter-label {
    -fx-font-size: 14px;
    -fx-font-weight: bold;
    -fx-text-fill: #4a5568;
}

.stock-filter {
    -fx-background-color: #edf2f7;
    -fx-text-fill: #4a5568;
    -fx-font-size: 13px;
    -fx-font-weight: 600;
    -fx-background-radius: 8px;
    -fx-padding: 8px 16px;
    -fx-cursor: hand;
}

.stock-filter:hover {
    -fx-background-color: #e2e8f0;
}

.stock-filter-active {
    -fx-background-color: linear-gradient(from 0% 0% to 100% 100%, #1e3a5f 0%, #2c5282 100%);
    -fx-text-fill: white;
}

/* Stock Table */
.stock-table-header {
    -fx-background-color: linear-gradient(from 0% 0% to 100% 100%, #1e3a5f 0%, #2c5282 100%);
    -fx-background-radius: 10px 10px 0 0;
    -fx-padding: 15px 10px;
}

.stock-header-cell {
    -fx-text-fill: white;
    -fx-font-size: 14px;
    -fx-font-weight: bold;
    -fx-padding: 0 10px;
}

.stock-table-body {
    -fx-background-color: white;
    -fx-background-radius: 0 0 10px 10px;
    -fx-effect: dropshadow(gaussian, rgba(0, 0, 0, 0.1), 8, 0, 0, 2);
}

.stock-row-odd {
    -fx-background-color: #f8fafc;
    -fx-padding: 12px 10px;
}

.stock-row-even {
    -fx-background-color: white;
    -fx-padding: 12px 10px;
}

.stock-row-odd:hover, .stock-row-even:hover {
    -fx-background-color: #e2e8f0;
}

.stock-cell {
    -fx-font-size: 13px;
    -fx-text-fill: #2d3748;
    -fx-padding: 0 10px;
}

.stock-qty-label {
    -fx-font-size: 14px;
    -fx-font-weight: bold;
    -fx-padding: 5px 15px;
    -fx-background-radius: 6px;
}

.stock-qty-ok {
    -fx-background-color: #d4edda;
    -fx-text-fill: #155724;
}

.stock-qty-low {
    -fx-background-color: #fff3cd;
    -fx-text-fill: #856404;
}

.stock-qty-out {
    -fx-background-color: #f8d7da;
    -fx-text-fill: #721c24;
}

.status-ok {
    -fx-text-fill: #28a745;
    -fx-font-weight: bold;
}

.status-low {
    -fx-text-fill: #ffc107;
    -fx-font-weight: bold;
}

.status-out {
    -fx-text-fill: #dc3545;
    -fx-font-weight: bold;
}

.stock-add-btn {
    -fx-background-color: #28a745;
    -fx-text-fill: white;
    -fx-font-size: 12px;
    -fx-font-weight: bold;
    -fx-background-radius: 6px;
    -fx-padding: 5px 12px;
    -fx-cursor: hand;
}

.stock-add-btn:hover {
    -fx-background-color: #218838;
}

.stock-remove-btn {
    -fx-background-color: #dc3545;
    -fx-text-fill: white;
    -fx-font-size: 12px;
    -fx-font-weight: bold;
    -fx-background-radius: 6px;
    -fx-padding: 5px 12px;
    -fx-cursor: hand;
}

.stock-remove-btn:hover {
    -fx-background-color: #c82333;
}

.stock-status {
    -fx-font-size: 14px;
    -fx-text-fill: #4a5568;
    -fx-font-weight: 600;
}

/* ========== SALES POS INTERFACE ========== */

.category-btn {
    -fx-background-color: #e8e8e8;
    -fx-text-fill: #333;
    -fx-font-size: 12;
    -fx-padding: 8px 15px;
    -fx-border-radius: 5;
    -fx-cursor: hand;
}

.category-btn:hover {
    -fx-background-color: #d0d0d0;
}

.category-btn-active {
    -fx-background-color: #3498db;
    -fx-text-fill: white;
    -fx-font-size: 12;
    -fx-padding: 8px 15px;
    -fx-border-radius: 5;
    -fx-cursor: hand;
    -fx-font-weight: bold;
}

.products-scroll {
    -fx-padding: 0;
    -fx-border-color: #ddd;
    -fx-border-radius: 5;
}

.products-grid {
    -fx-spacing: 15;
    -fx-padding: 15;
}

.product-card {
    -fx-border-color: #ddd;
    -fx-border-radius: 8;
    -fx-padding: 10;
    -fx-spacing: 8;
    -fx-background-color: #fff;
}

.product-card:hover {
    -fx-border-color: #3498db;
    -fx-effect: dropshadow(gaussian, rgba(52, 152, 219, 0.3), 10, 0, 0, 3);
}

.cart-section {
    -fx-border-color: #ddd;
    -fx-border-radius: 8;
    -fx-padding: 15;
    -fx-background-color: #f9f9f9;
}

.cart-scroll {
    -fx-border-color: #ddd;
    -fx-border-radius: 5;
}

.cart-summary {
    -fx-border-color: #ddd;
    -fx-border-radius: 5;
    -fx-padding: 10;
    -fx-background-color: #fff;
}

.summary-label {
    -fx-font-size: 12;
    -fx-text-fill: #666;
}

.summary-value {
    -fx-font-size: 12;
    -fx-font-weight: bold;
    -fx-text-fill: #333;
}

.summary-value-total {
    -fx-font-size: 14;
    -fx-font-weight: bold;
    -fx-text-fill: #27ae60;
}

.confirm-btn {
    -fx-background-color: #27ae60;
    -fx-text-fill: white;
    -fx-font-size: 13;
    -fx-font-weight: bold;
    -fx-padding: 10px 20px;
    -fx-border-radius: 5;
    -fx-cursor: hand;
}

.confirm-btn:hover {
    -fx-background-color: #229954;
}

.cancel-btn {
    -fx-background-color: #e74c3c;
    -fx-text-fill: white;
    -fx-font-size: 13;
    -fx-font-weight: bold;
    -fx-padding: 10px 20px;
    -fx-border-radius: 5;
    -fx-cursor: hand;
}

.cancel-btn:hover {
    -fx-background-color: #c0392b;
}

/* Beauty page list-only rows */
.beauty-list-row {
    -fx-background-color: #ffffff;
    -fx-background-radius: 10;
    -fx-border-color: #e7eaf0;
    -fx-border-radius: 10;
    -fx-padding: 14;
}

.beauty-list-row .product-name {
    -fx-font-size: 16px;
    -fx-font-weight: 700;
    -fx-text-fill: #1f2937;
}

.product-id-label {
    -fx-font-size: 12px;
    -fx-text-fill: #6b7280;
    -fx-font-weight: 600;
}

/* ===== Global forced dark theme + bold text ===== */
.root,
.home-page-bg,
.anchor-pane,
.vbox,
.hbox,
.stack-pane,
.border-pane,
.grid-pane,
.tile-pane,
.flow-pane,
.scroll-pane,
.scroll-pane > .viewport,
.table-view,
.list-view,
.tree-view,
.tab-pane .tab-content-area {
    -fx-background-color: #000000;
    -fx-background-image: none;
}

.label,
.text,
.button,
.toggle-button,
.check-box,
.radio-button,
.menu-button,
.hyperlink,
.tab .tab-label,
.table-view .column-header .label,
.table-cell,
.list-cell,
.tree-cell,
.combo-box,
.combo-box-base,
.choice-box,
.text-field,
.password-field,
.text-area,
.spinner .text-field,
.date-picker,
.date-picker .text-field {
    -fx-text-fill: #f5f5f5;
    -fx-font-weight: 700;
}

.text-field,
.password-field,
.text-area,
.combo-box-base,
.choice-box,
.date-picker,
.spinner .text-field {
    -fx-background-color: #111111;
    -fx-border-color: #333333;
}

.chart,
.chart-plot-background,
.chart-content,
.chart-vertical-grid-lines,
.chart-horizontal-grid-lines {
    -fx-background-color: #000000;
}

.axis,
.axis-label,
.axis-tick-mark,
.axis-minor-tick-mark,
.chart-legend-item,
.chart-legend-item-symbol,
.chart-title {
    -fx-text-fill: #f5f5f5;
    -fx-font-weight: 700;
}

/* Explicit dark overrides for login/dashboard classes that were light */
.home-page-bg,
.left-panel,
.right-panel,
.dashboard-header,
.dashboard-main,
.content-card,
.dashboard-side-column .content-card,
.home-card,
.home-status,
.modern-table,
.table-view,
.table-view .column-header-background,
.table-row-cell,
.table-row-cell:odd,
.table-row-cell:even,
.list-cell,
.list-view,
.combo-box-popup .list-view,
.menu-item,
.context-menu {
    -fx-background-color: #000000;
    -fx-background-image: none;
    -fx-border-color: #222222;
}

.subtitle,
.field-label,
.login-title,
.signup-text,
.forgot-link,
.signup-link,
.link-button,
.dashboard-title,
.dashboard-welcome,
.section-title,
.chart-placeholder,
.activity-item,
.cart-status-label,
.product-id-label {
    -fx-text-fill: #f5f5f5;
    -fx-font-weight: 700;
}

.text-field,
.password-field,
.text-area,
.table-view,
.list-view,
.combo-box,
.combo-box-base,
.date-picker,
.date-picker .text-field,
spinner .text-field,
.choice-box {
    -fx-control-inner-background: #111111;
    -fx-background-color: #111111;
    -fx-text-fill: #f5f5f5;
    -fx-prompt-text-fill: #9ca3af;
    -fx-border-color: #333333;
}

.table-view .column-header,
.table-view .filler,
.table-view .corner {
    -fx-background-color: #111111;
}

/* ===== Home Add Product Overlay ===== */
.product-modal-overlay {
    -fx-background-color: rgba(0, 0, 0, 0.62);
}

.product-modal-panel {
    -fx-background-color: #111111;
    -fx-background-radius: 10;
    -fx-border-color: #333333;
    -fx-border-radius: 10;
    -fx-padding: 14;
}

.product-close-btn {
    -fx-background-color: transparent;
    -fx-text-fill: #f5f5f5;
    -fx-font-size: 16px;
    -fx-font-weight: 700;
    -fx-cursor: hand;
}

.product-close-btn:hover {
    -fx-font-weight: 900;
    -fx-text-fill: #ffffff;
    -fx-scale-x: 1.08;
    -fx-scale-y: 1.08;
}

.product-form-label {
    -fx-text-fill: #f5f5f5;
    -fx-font-size: 14px;
    -fx-font-weight: 700;
}

.product-form-field {
    -fx-background-color: #0f0f0f;
    -fx-text-fill: #f5f5f5;
    -fx-font-weight: 700;
    -fx-border-color: #333333;
    -fx-border-radius: 4;
    -fx-background-radius: 4;
}

.product-image-preview {
    -fx-border-color: #3a3a3a;
    -fx-border-width: 1;
    -fx-background-color: #0c0c0c;
}

.product-image-label {
    -fx-text-fill: #d1d5db;
    -fx-font-size: 11px;
    -fx-font-weight: 700;
}

.product-action-btn {
    -fx-text-fill: #f5f5f5;
    -fx-font-weight: 800;
    -fx-font-size: 14px;
    -fx-padding: 8 14;
    -fx-background-radius: 4;
    -fx-cursor: hand;
}

.product-action-add {
    -fx-background-color: #1f9d72;
}

.product-action-update {
    -fx-background-color: #1b8f6a;
}

.product-action-clear {
    -fx-background-color: #177f5e;
}

.product-action-delete {
    -fx-background-color: #146f53;
}

.product-action-import {
    -fx-background-color: #0f8b68;
}

/* Keep all typed input fields dark even on focus/hover */
.text-input,
.text-field,
.password-field,
.text-area,
.combo-box-base,
.date-picker,
spinner .text-field,
.choice-box {
    -fx-control-inner-background: #111111;
    -fx-background-color: #111111;
    -fx-text-fill: #f5f5f5;
    -fx-prompt-text-fill: #9ca3af;
    -fx-border-color: #333333;
}

.text-input:focused,
.text-input:hover,
.text-field:focused,
.text-field:hover,
.password-field:focused,
.password-field:hover,
.text-area:focused,
.text-area:hover,
.combo-box-base:focused,
.combo-box-base:hover,
.date-picker:focused,
.date-picker:hover,
spinner .text-field:focused,
spinner .text-field:hover {
    -fx-control-inner-background: #111111;
    -fx-background-color: #111111;
    -fx-border-color: #4b5563;
    -fx-text-fill: #f5f5f5;
}

.text-area .content {
    -fx-background-color: #111111;
}

/* Compact button sizing so labels fit fully across pages */
.button {
    -fx-font-size: 14px;
    -fx-padding: 8 14;
    -fx-alignment: center;
}

.due-toggle-black {
    -fx-background-color: #000000;
    -fx-text-fill: #f5f5f5;
    -fx-border-color: #3f3f46;
    -fx-border-radius: 8;
    -fx-background-radius: 8;
    -fx-padding: 6 12;
}

.due-toggle-black:hover {
    -fx-background-color: #111111;
    -fx-border-color: #52525b;
}

.due-toggle-black:selected {
    -fx-background-color: #18181b;
    -fx-border-color: #71717a;
}
